args.command:
pwd && ls -la && mkdir -p app/src && cat > app/package.json <<'EOF'
{
  "name": "demo-neon-auth-app",
  "private": true,
  "type": "module",
  "scripts": {
    "check": "node src/check.js"
  }
}
EOF
cat > app/neon.ts <<'EOF'
import { defineConfig } from "@neon/config/v1";

export default defineConfig({
  project: "demo-project",
  auth: true,
});
EOF
cat > app/src/check.js <<'EOF'
import fs from 'fs';
const neon = fs.readFileSync(new URL('../neon.ts', import.meta.url), 'utf8');
if (!neon.includes('auth: true')) {
  console.error('auth not enabled');
  process.exit(1);
}
console.log('neon auth config present');
EOF
node app/src/check.js
